NAME = 'NlCanisius1939: Petrus Canisius Translation'
BOOK = 'I Corinthians'

CHAPTERS = {
    1: {
        1: 'Paulus, apostel van Christus Jesus, geroepen door Gods wil, en broeder Sóstenes:',
        2: 'aan de Kerk Gods te Korinte, aan hen die geheiligd zijn door Christus Jesus, aan de uitverkoren heiligen, en aan allen die de naam van Jesus Christus aanroepen in iedere plaats, zowel bij hen als bij ons:',
        3: 'Genade zij u en vrede van God onzen Vader, en van den Heer Jesus Christus.',
        4: 'Ten allen tijde dank ik God om u voor Gods genade, die u gegeven is in Christus Jesus;',
        5: 'want door Hem zijt gij rijk geworden in ieder opzicht, —in alle woord en in alle kennis',
        6: 'in dezelfde mate als de belijdenis van Christus vastheid onder u heeft gekregen.',
        7: 'En zo staat gij in geen enkele genadegave ten achter al de tijd, dat gij de openbaring afwacht van onzen Heer Jesus Christus.',
        8: 'Bovendien zal Deze u vast doen staan ten einde toe, zodat gij onberispelijk zijn zult op de dag van onzen Heer Jesus Christus.',
        9: 'God is getrouw; Hij door wien gij geroepen zijt tot de gemeenschap met zijn Zoon, Jesus Christus onzen Heer.',
        10: 'Broeders, ik bezweer u uit naam van onzen Heer Jesus Christus, dat gij allen hetzelfde spreekt en dat er onder u geen scheuringen zijn, maar dat gij volkomen één zijt in dezelfde gezindheid en dezelfde overtuiging.',
        11: 'Want, mijn broeders, door de lieden van Chloë is me over u bekend geworden, dat er twisten onder u zijn.',
        12: 'Ik bedoel dit: Iedereen van u zegt: "Ik ben van Paulus, ik van Apollo, ik van Kefas, ik van Christus."',
        13: 'Is Christus soms verdeeld? Of is Paulus soms voor u gekruisigd, of zijt gij in Paulus’ naam gedoopt?',
        14: 'Ik ben er dankbaar om, dat ik niemand van u gedoopt hebt behalve Krispus en Gajus,',
        15: 'zodat men niet zeggen kan, dat gij in mijn naam zijt gedoopt.',
        16: 'Ook Stéfanas’ familie heb ik nog gedoopt; overigens weet ik niet, dat ik iemand anders gedoopt heb.',
        17: 'Want Christus heeft mij niet gezonden om te dopen, maar om het Evangelie te verkondigen: niet met wijsheid van woorden, opdat het Kruis van Christus zijn betekenis niet zou verliezen.',
        18: 'Immers de prediking van het Kruis is wel een dwaasheid voor hen, die verloren gaan, maar voor ons, die behouden worden, is ze een kracht Gods.',
        19: 'Want er staat geschreven: "Ik zal de wijsheid der wijzen verdelgen, En het beleid der verstandigen te niet doen."',
        20: 'Waar is de wijze? Waar de schriftgeleerde? Waar de redetwister dezer wereld? Heeft God de wijsheid dezer wereld niet dwaas gemaakt?',
        21: 'Want daar volgens het bestel van Gods wijsheid de wereld niet door de wijsheid tot de kennis van God is gekomen, zo heeft het God behaagd, de gelovigen zalig te maken door de dwaasheid der prediking.',
        22: 'Terwijl de Joden tekenen eisen, en de Grieken wijsheid zoeken,',
        23: 'preken wij Christus gekruisigd, voor de Joden een ergernis en voor de heidenen een dwaasheid,',
        24: 'maar voor hen, die geroepen zijn, Joden zowel als Grieken, een Christus, Gods kracht en Gods wijsheid.',
        25: 'Want het dwaze van God is wijzer dan de mensen, en het zwakke van God is krachtiger dan de mensen.',
        26: 'Inderdaad, broeders, denkt eens aan uw eigen roeping terug; niet velen waren wijzen naar het vlees, niet velen machtig, niet velen aanzienlijk.',
        27: 'Neen, het dwaze der wereld heeft God uitverkoren, om de wijzen beschaamd te maken; en het zwakke der wereld heeft God uitverkoren, om het sterke te beschamen;',
        28: 'en het onaanzienlijke der wereld en het onbeduidende heeft God uitverkoren: alles wat niets is, om te niet te doen, wat iets is,',
        29: 'opdat geen vlees zou roemen voor God.',
        30: 'Door Hem toch behoort gij aan Christus Jesus, die ons door God geworden is: Wijsheid, Gerechtigheid, Heiliging en Verlossing;',
        31: 'opdat gelijk geschreven staat: "Hij die roemt, Roeme in den Heer."',
    },
    2: {
        1: 'Toen ik dus tot u kwam, broeders, ben ik niet met macht van woord of wijsheid u de getuigenis Gods komen verkondigen.',
        2: 'En ik was besloten, onder u niets te kennen, dan Jesus Christus, en Dien gekruisigd.',
        3: 'Ik trad bij u op in zwakheid, vrees, en grote siddering;',
        4: 'mijn spreken en preken steunden niet op overtuigende woorden van wijsheid, maar op de overtuiging des Geestes en der kracht,',
        5: 'opdat uw geloof niet zou rusten op wijsheid van mensen, maar op Gods kracht.',
        6: 'Toch preken we wijsheid onder de volmaakten; maar geen wijsheid dezer wereld, noch der machten dezer wereld, die vernietigd zullen worden.',
        7: 'Ja, we verkondigen een Wijsheid Gods, een geheimnisvolle, een verborgene, welke God vóór de tijden heeft voorbestemd tot onze glorie,',
        8: 'die geen der machten dezer wereld heeft gekend, —want zo ze haar gekend hadden, zouden ze den Heer der glorie niet hebben gekruisigd,',
        9: 'maar een, waarvan geschreven staat: "Wat het oog niet heeft gezien, Noch het oor heeft gehoord, Noch in het hart van een mens is opgekomen, Wat God heeft bereid voor hen, die Hem liefhebben."',
        10: 'Immers, òns heeft God ze geopenbaard door den Geest. Want de Geest doorgrondt alles, zelfs de verborgenheden Gods.',
        11: 'Wie der mensen toch kent de verborgenheden van den mens, behalve de geest van den mens, die in hem is? Zo ook kent niemand die van God, tenzij de Geest van God.',
        12: 'Welnu, we hebben niet de geest der wereld ontvangen, maar den Geest, die uit God is, opdat we zouden kennen wat ons door God is geschonken.',
        13: 'En dat spreken we ook uit, niet met woorden door menselijke wijsheid aangeleerd, maar door den Geest onderwezen; het geestelijke met het geestelijke verenigend.',
        14: 'Maar de verstands-mens aanvaardt niet wat van Gods Geest komt, want het is hem een dwaasheid; en hij kàn het zelfs niet kennen, omdat het op geestelijke wijze moet beoordeeld worden.',
        15: 'De geestelijke mens daarentegen beoordeelt alles, zonder zelf door iemand beoordeeld te worden.',
        16: '"Wie toch kent het inzicht des Heren, dat hij Hem zou onderrichten?" Welnu, wij hebben het inzicht van Christus.',
    },
    3: {
        1: 'Ook tot u, broeders, kon ik niet spreken als tot geestelijken, maar als tot vleselijken, als tot kinderkens in Christus.',
        2: 'Melk heb ik u te drinken gegeven, geen vaste spijs; want gij kondt er nog niet tegen. En ook nu kunt gij het nog niet;',
        3: 'want nog zijt gij vleselijk. Immers, wanneer er onder u naijver is en twist, zijt gij dan niet vleselijk, en wandelt gij niet volgens den mens?',
        4: 'Want zolang de één zegt: "Ik ben van Paulus", en de ander: "Ik ben van Apollo", zijt gij dan niet louter mensen?',
        5: 'Wat toch is Apollo? Wat is Paulus? Dienaars, door wier toedoen gij het geloof hebt ontvangen; elk op de wijze als de Heer hem gegeven heeft.',
        6: 'Ik heb geplant, Apollo heeft begoten, maar God heeft wasdom verleend.',
        7: 'En daarom, noch hij die plant, noch hij die begiet, betekent iets, maar God die wasdom geeft.',
        8: 'Toch zijn ze één, hij die plant en hij die begiet; en elk zal zijn eigen loon ontvangen, overeenkomstig eigen arbeid.',
        9: 'Wij zijn Gods medearbeiders; gij zijt Gods akker, Gods bouwwerk.',
        10: 'Volgens Gods genade, mij geschonken, heb ik als een wijs bouwmeester het fundament gelegd, en een ander bouwt er op. Maar iedereen moet toezien, hoe hij daarop bouwt.',
        11: 'Want niemand mag een ander fundament plaatsen, dan wat gelegd is, en dat is Jesus Christus.',
        12: 'Onverschillig of men op dit fundament voortbouwt met goud of zilver, met edelstenen, hout, stro of riet;',
        13: 'eens zal ieders werk bekend worden gemaakt. Immers de Dag zal het aantonen; want in vuur openbaart hij zich, en het vuur zal uitwijzen, van wat gehalte het werk van een ieder is.',
        14: 'Houdt het werk, dat hij heeft opgebouwd, stand, dan zal hij loon ontvangen.',
        15: 'Zo zijn werk verbrandt, dan zal hij schade lijden; hij zal wel behouden worden, maar zó, dat hij eerst door het vuur moet.',
        16: 'Weet gij niet, dat gij Gods tempel zijt en dat Gods Geest in u woont?',
        17: 'Zo iemand Gods tempel ten verderve brengt, dan zal God ook hem verderven. Want heilig is Gods tempel, en dat zijt gij.',
        18: 'Niemand bedriege zichzelf Zo iemand wijs onder u meent te zijn, hij moet dwaas naar deze wereld worden, om wijs te zijn.',
        19: 'Immers de wijsheid dezer wereld is dwaasheid voor God. Want er staat geschreven: "Hij, die de wijzen in hun eigen arglistigheid vat."',
        20: 'En eveneens: "De Heer weet, dat de gedachten der wijzen ijdel zijn."',
        21: 'Niemand mag dus op mensen roemen. Want alles is het uwe:',
        22: 'Paulus, Apollo, Kefas, wereld, leven, dood, heden, toekomst. Alles is het uwe;',
        23: 'maar gij behoort aan Christus, en Christus aan God.',
    },
    4: {
        1: 'Men moet ons zonder meer als dienaars van Christus beschouwen, en beheerders van Gods geheimenissen.',
        2: 'Welnu, van de beheerders wordt slechts gevorderd, dat ze trouw worden bevonden.',
        3: 'En dàn is er mij weinig aan gelegen, of ik door u of een menselijk gericht word geoordeeld. Ja, ik oordeel mezelf niet eens;',
        4: 'want wel ben ik mezelf niets bewust, maar daardoor ben ik niet gerechtvaardigd. De Heer is het, die mij oordeelt.',
        5: 'Daarom, oordeelt niet vóór de tijd, niet voordat de Heer komt, die zowel de verborgenheden der duisternis aan het licht zal brengen, als de bedoelingen der harten openbaren. En dan zal een ieder lof ontvangen van God.',
        6: 'Broeders, ik heb deze dingen toegepast op mijzelf en Apollo terwille van u, opdat gij in ons voorbeeld zoudt leren: "Niet boven hetgeen geschreven staat;" opdat de een zich niet opblaast ten voordele van een ander en ten nadele van een derde.',
        7: 'Wie eigenlijk houdt u voor zo iets bijzonders? Of wat hebt ge, dat ge niet verkregen hebt? En zo ge het verkregen hebt, wat pocht ge dan, als hadt ge het niet verkregen?',
        8: 'Zeker wel, gij zijt reeds verzadigd! Nu reeds zijt gij rijk! Buiten ons om bezit gij het koningschap! Och, was het toch werkelijk waar, dat gij het koningschap bezat, dan mochten wij er misschien wel in delen!',
        9: 'Want waarlijk, ik geloof, dat God ons, Apostelen, de laatste plaats heeft toegewezen, als ter dood veroordeelden; want wij zijn een schouwspel geworden voor de wereld, voor engelen en mensen!',
        10: 'Wij, wij zijn dwazen terwille van Christus; gij echter wijzen in Christus. Wij zijn zwak, gij zijt sterk. Gij zijt geëerd, wij veracht.',
        11: 'Tot op dit uur lijden we honger, dorst en naaktheid; we worden mishandeld, we zwerven rond;',
        12: 'in handenarbeid putten we ons uit. Worden we gescholden, we zegenen; worden we vervolgd, we verdragen het;',
        13: 'worden we gelasterd, we spreken ten goede. Als uitvaagsel der wereld zijn we geworden, het grootste uitschot tot op de huidige dag.',
        14: 'Ik schrijf u deze dingen, niet om u te beschamen, maar om u terecht te wijzen, als mijn geliefde kinderen.',
        15: 'Want al hadt gij ook tienduizend leermeesters in Christus, vele vaders hebt gij niet; ik heb u door het Evangelie in Jesus Christus verwekt.',
        16: 'En daarom smeek ik u: weest mijn navolgers.',
        17: 'Om dezelfde reden heb ik Timóteus naar u toe gezonden, die mijn geliefde en getrouwe zoon is in den Heer; hij zal u mijn wegen in Christus in herinnering brengen, zoals ik ze overal in alle kerken leer.',
        18: 'Sommigen zijn verwaand in de overtuiging, dat ik toch niet bij u kom.',
        19: 'Toch zal ik spoedig bij u komen, zo de Heer het wil; dan zal ik me eens op de hoogte stellen, niet van het woord van die verwaanden, maar van hun kracht.',
        20: 'Want het koninkrijk Gods bestaat niet in woorden, maar in kracht.',
        21: 'Wat verkiest gij? Zal ik met de roede tot u komen, of met liefde en zachtmoedigheid?',
    },
    5: {
        1: 'Algemeen hoort men, dat er ontucht onder u voorkomt, en wel zulk een ontucht, als er zelfs onder de heidenen niet bestaat: dat namelijk iemand de vrouw van zijn vader bezit.',
        2: 'En dan zijt gij nog opgeblazen! Waart gij niet beter terneergeslagen geweest? Dan was hij, die zo iets bedreven heeft, wel uit uw midden verwijderd!',
        3: 'Ik zelf toch, lichamelijk afwezig, maar tegenwoordig met de geest, heb reeds, als was ik tegenwoordig, het oordeel geveld over hem, die zo iets gedaan heeft.',
        4: 'In de Naam van den Heer Jesus: gij en mijn geest, toegerust met de kracht van onzen Heer Jesus:',
        5: 'wij leveren hem over aan den satan tot verderf van het vlees, opdat de geest wordt behouden op de dag des Heren.',
        6: 'Uw roemen staat u niet fraai! Weet gij niet, dat een weinig zuurdeeg geheel het deeg verzuurt?',
        7: 'Doet het oude zuurdeeg weg, opdat gij vers deeg worden moogt; gij zijt toch ongedesemd brood! Want ook ons Pascha is geslacht: en dat is Christus.',
        8: 'Laat ons dus feest vieren, niet met het oude zuurdeeg, noch met het zuurdeeg van slechtheid en boosheid, maar met de ongedesemde broden van reinheid en waarheid.',
        9: 'In mijn brief heb ik u geschreven, dat gij geen omgang moogt hebben met ontuchtigen.',
        10: 'Ik schreef niet: met alle ontuchtigen dezer wereld, of met alle hebzuchtigen en dieven, of alle afgodendienaars;',
        11: 'anders zoudt gij de wereld moeten verlaten. Maar ik schreef u, geen omgang te hebben met iemand, die zich broeder noemt en toch een ontuchtige is, of een hebzuchtige, een afgodendienaar, lasteraar, dronkaard of dief; en met zo iemand zelfs niet te eten.',
        12: 'Want met welk recht zou ik hen oordelen, die buiten staan? Neen, oordeelt hen, die binnen zijn;',
        13: 'God zal oordelen, die buiten staan. Verwijdert den boze uit uw midden!',
    },
    6: {
        1: 'Wanneer iemand van u met een ander een geschil heeft, durft hij dan recht zoeken bij de ongerechtigen, en niet bij de heiligen?',
        2: 'Weet gij dan niet, dat de heiligen de wereld zullen richten? En zo zelfs de wereld door u wordt gericht, zoudt gij dan onbevoegd zijn voor onbeduidende geschillen?',
        3: 'Weet gij niet, dat wij engelen zullen richten? Hoeveel te meer dus de kwesties van het dagelijks leven.',
        4: 'En toch laat gij bij uw dagelijkse geschillen juist hen daarover zitting houden, die door de gemeente worden veracht.',
        5: 'Ik zeg het tot uw beschaming. Is er dan onder u geen enkel verstandig man, die tussen zijn broeders uitspraak zou kunnen doen?',
        6: 'In plaats daarvan daagt de ene broeder den ander voor het gerecht, en dan nog wel ten overstaan van ongelovigen.',
        7: 'Ja, het is op zichzelf voor u al meer dan erg, dat gij met elkander geschillen hebt. Waarom lijdt gij niet liever onrecht? Waarom lijdt gij niet liever schade?',
        8: 'In plaats daarvan doet gij zelf onrecht en schade, en dat nog wel aan broeders.',
        9: 'Weet gij dan niet, dat zij die onrecht doen, geen deel zullen hebben aan het koninkrijk Gods? Bedriegt u niet. Ontuchtigen, afgodendienaars, overspelers, wellustelingen, knapenschenners,',
        10: 'dieven, hebzuchtigen, dronkaards, lasteraars en rovers zullen geen deel hebben aan het koninkrijk Gods.',
        11: 'En dit waren sommigen van u. Maar gij zijt rein gewassen, gij zijt geheiligd, gij zijt gerechtvaardigd in de naam van den Heer Jesus Christus en door den Geest van onzen God.',
        12: 'Alles is mij geoorloofd! Maar alles is niet heilzaam! Alles is mij geoorloofd! Maar ik zal me door niets laten overheersen!',
        13: 'De spijzen zijn voor de buik, en de buik is voor de spijzen; maar God zal beide aan de vernietiging prijsgeven. Het lichaam daarentegen is niet voor de ontucht, maar het behoort aan den Heer, en de Heer aan het lichaam.',
        14: 'God heeft den Heer opgewekt, en Hij zal ook ons doen verrijzen door zijn kracht.',
        15: 'Weet gij soms niet, dat uw lichamen ledematen zijn van Christus? Zal ik ze dan doen ophouden, ledematen van Christus te zijn, om er ledematen ener deerne van te maken! Dat nooit!',
        16: 'Maar weet gij ook niet, dat hij, die zich met een deerne afgeeft, met haar één lichaam is? Want Hij zegt: "Deze twee zullen één vlees zijn."',
        17: 'Hij daarentegen, die den Heer aanhangt, is één geest met Hem.',
        18: 'Vlucht de ontucht! Iedere zonde, die de mens bedrijft, is buiten het lichaam, maar de ontuchtige zondigt tegen zijn eigen lichaam.',
        19: 'Of weet gij niet, dat uw lichaam een tempel is van den heiligen Geest, die in u woont, en dien gij van God hebt ontvangen; ook dat gij uzelf niet toebehoort,',
        20: 'daar gij duur zijt gekocht? Verheerlijkt dus God in uw lichaam!',
    },
    7: {
        1: 'Wat de dingen betreft, waarover gij geschreven hebt: het is goed voor een mens, geen vrouw aan te raken;',
        2: 'maar ter vermijding van allerlei ontucht moet toch iedere man zijn eigen vrouw behouden, en iedere vrouw haar eigen man.',
        3: 'De man moet aan de vrouw zijn plicht vervullen, zoals ook de vrouw aan den man.',
        4: 'De vrouw heeft geen vrije beschikking over haar eigen lichaam, maar de man. Eveneens heeft ook de man geen vrije beschikking over zijn eigen lichaam, maar de vrouw.',
        5: 'Weigert niet aan elkander, dan alleen met onderling goedvinden en voor een bepaalde tijd, om u aan het gebed te wijden; en gaat er dan weer toe over, opdat de satan u niet bekoort door uw onthouding.',
        6: 'Dit laatste echter bedoel ik als een verlof, en niet als bevel.',
        7: 'Integendeel, ik zou willen, dat alle mensen waren zoals ikzelf; maar iedereen heeft van God een persoonlijke gave, de één deze, gene weer een andere.',
        8: 'Tot de ongehuwden en de weduwen zeg ik: het is goed voor hen, zo ze blijven, zoals ikzelf ben',
        9: 'Maar zo ze zich niet kunnen beheersen, laten ze dan trouwen. Want het is beter te trouwen dan te verbranden.',
        10: 'Aan de gehuwden beveel niet ik maar de Heer, dat de vrouw zich niet mag scheiden van den man;',
        11: 'en zo ze toch gescheiden is, dat ze dan ongehuwd moet blijven of zich met den man moet verzoenen; ook dat de man de vrouw niet mag verstoten.',
        12: 'Aan de overigen zeg ik, niet de Heer: Wanneer een broeder een ongelovige vrouw heeft, en deze bewilligt er in, met hem samen te wonen, dan mag hij haar niet verstoten;',
        13: 'eveneens, wanneer een vrouw een ongelovigen man heeft, en deze er in bewilligt, met haar samen te wonen, dan mag ze den man niet verstoten.',
        14: 'Want de ongelovige man is geheiligd door de vrouw, en de ongelovige vrouw geheiligd door den broeder; anders toch waren uw kinderen onrein, terwijl ze inderdaad heilig zijn.',
        15: 'Maar wanneer de ongelovige scheiden wil, laat hem scheiden; in zulke gevallen is de broeder en de zuster niet gebonden. God heeft u toch tot vrede geroepen;',
        16: 'want hoe weet ge, vrouw, of ge den man zult redden; en gij, man, hoe weet ge, of ge de vrouw redden zult?',
        17: 'Iedereen heeft dus zó te leven, als de Heer hem heeft toegedeeld, zoals God hem heeft geroepen. Zo verorden ik in alle kerken.',
        18: 'Is iemand geroepen, nadat hij de besnijdenis had ontvangen, hij moet ze niet wegwerken; is iemand als onbesnedene geroepen, hij moet zich niet laten besnijden.',
        19: 'De besnijdenis is niets, de onbesnedenheid evenmin, maar alleen de onderhouding van Gods geboden.',
        20: 'Laat iedereen in de staat blijven, waarin hij geroepen is.',
        21: 'Zijt ge geroepen als slaaf, maak u daarover niet bekommerd; maar zo óók gij vrij kunt worden, maak dan liever van de gelegenheid gebruik.',
        22: 'Immers een slaaf, die geroepen is in den Heer, is een vrijgelatene van den Heer; zoals een vrije, die geroepen is, de slaaf is van Christus.',
        23: 'Duur zijt gij gekocht; weest geen mensen-slaven.',
        24: 'Broeders, laat iedereen voor God in de staat blijven, waarin hij geroepen werd.',
        25: 'Wat de maagden betreft, heb ik geen gebod des Heren; maar ik geef mijn gevoelen als iemand, die door Gods ontferming betrouwbaar is.',
        26: 'Welnu, ik ben er van overtuigd, dat om de aanstaande Nood dit het best is: dat namelijk iemand liefst zó blijft, als hij is.',
        27: 'Zijt ge aan een vrouw verbonden, zoek dan geen scheiding.',
        28: 'Zijt ge niet aan een vrouw verbonden, zoek dan geen vrouw; doch ook al huwt ge, ge zondigt niet; en als een maagd trouwt, zondigt ze niet. Maar zulke personen zullen bekommernissen hebben naar het vlees, en die wilde ik u besparen.',
        29: 'Dit toch heb ik te zeggen, broeders. De tijd is kort. Daaruit volgt, dat zelfs zij, die vrouwen hebben, moeten zijn, als hadden zij ze niet;',
        30: 'en zij die wenen, alsof ze niet weenden; en zij die blijde zijn, als verblijdden ze zich niet; en zij die kopen, als behielden ze het niet;',
        31: 'en zij die van de wereld genieten, als hadden ze er niets mee op. Want de gedaante dezer wereld gaat voorbij;',
        32: 'en daarom wil ik, dat gij zonder zorgen zijt. —De òngehuwde is bezorgd over de dingen des Heren, hoe hij behagen zal aan den Heer;',
        33: 'maar de gehuwde is bezorgd over de dingen der wereld, hoe hij behagen zal aan de vrouw;',
        34: 'en hij is verdeeld. Eveneens is ook de ongehuwde vrouw en de maagd bezorgd over de dingen des Heren, om heilig te zijn naar lichaam en ziel, terwijl de gehuwde bezorgd is over de dingen der wereld, hoe ze den man zal behagen.',
        35: 'Ik zeg dit tot uw eigen bestwil, niet om u een strik om te doen, maar opdat gij onwankelbaar zoudt zijn in de eerbaarheid en in de toewijding aan den Heer.',
        36: 'Zo iemand schande denkt te brengen op zijn jonge dochter, als ze eens over de jaren komt, en de zaken dus toch haar verloop moeten hebben: hij doe, wat hij wil; hij zondigt niet. Laat ze trouwen.',
        37: 'Maar hij, die onwankelbaar in zijn gevoelen volhardt, die vrij van dwang zijn eigen wil kan volgen, en die bij zichzelf besloten heeft, zijn jonge dochter ongerept te bewaren, hij doet wèl.',
        38: 'Dus, die zijn dochter uithuwt, doet goed, en die ze niet uithuwt, doet beter.',
        39: 'Een vrouw is gebonden, zolang haar man leeft. Maar wanneer de man is ontslapen, dan is ze vrij te trouwen met wien ze wil, mits in den Heer.',
        40: 'Toch is ze gelukkiger, zo ze blijft, zoals ze is; volgens mijn gevoelen althans. En ik meen toch wel, Gods Geest te hebben.',
    },
    8: {
        1: 'Wat nu het offervlees betreft, weten we: "Allen hebben we kennis." Maar de kennis blaast op, de liefde bouwt op.',
        2: 'Zo iemand zich inbeeldt, iets te kennen, dan is zijn kennis nog niet, zoals ze wezen moet;',
        3: 'doch zo iemand liefde heeft tot God, dan is hij door Hem gekend.',
        4: 'Wat dus het eten van het offervlees aangaat, weten we, dat er eigenlijk geen afgod in de wereld bestaat, en dat er geen God is, behalve Eén.',
        5: 'Want al zijn er ook zogenaamde goden in de hemel of op aarde, en zó zijn er inderdaad veel goden en veel heren,',
        6: 'voor ons is er slechts één God, de Vader, uit wien alles voortkomt, en tot wien we geordend zijn, en één Heer Jesus Christus, door wien alle dingen, door wien ook wijzelf zijn.',
        7: 'Maar niet allen hebben die kennis. Sommigen toch, ook nu nog in de overtuiging, dat er werkelijk afgoden bestaan, eten het juist als offervlees, en hun geweten, zwak als het is, wordt er door bezoedeld.',
        8: 'Zeker, het eten zal ons niet voor God brengen: eten we niet, we zijn er niet minder om: eten we wel, we worden er niet beter van.',
        9: 'Toch moet gij toezien, dat uw recht de zwakken niet tot aanstoot wordt.',
        10: 'Want wanneer zo iemand u, den man van kennis, in een afgodstempel ziet aanliggen, zal dan het geweten van dien zwakken mens niet worden gestijfd in het eten der afgodenoffers?',
        11: 'Ja, dan gaat door uw kennis de zwakke verloren, de broeder, voor wien Christus gestorven is.',
        12: 'Maar door zó tegen de broeders te zondigen en hun zwak geweten te kwetsen, zondigt gij tegen Christus.',
        13: 'Daarom, zo het eten ergernis geeft aan mijn broeder, dan zal ik in eeuwigheid geen vlees meer eten, om mijn broeder niet te ergeren.',
    },
    9: {
        1: 'Ben ik niet vrij? Ben ik geen Apostel? Heb ik onzen Heer Jesus niet gezien? Zijt gij niet mijn werk in den Heer?',
        2: 'Zo ik in de opvatting van anderen geen Apostel ben, voor u ben ik het toch zeker wèl; gij zijt zelfs het zegel van mijn apostolaat in den Heer.',
        3: 'Ziedaar mijn antwoord aan hen, die iets op mij hebben aan te merken.',
        4: 'Hebben wij dan geen recht, te eten en te drinken?',
        5: 'Hebben wij geen recht, een zuster, een vrouw mee te nemen, zoals de overige apostelen, de broeders des Heren en Kefas?',
        6: 'Of hebben alleen ik en Bárnabas geen recht, ons van handenarbeid ontslagen te achten?',
        7: 'Wie dient er als soldaat op eigen kosten; wie plant een wijngaard en eet niet van zijn vruchten; of wie weidt een kudde, en voedt zich niet met de melk der kudde?',
        8: 'Spreek ik misschien zó naar menselijke opvatting, of zegt ook de Wet niet hetzelfde?',
        9: 'Inderdaad, in de Wet van Moses staat geschreven: "Een dorsenden os zult ge niet muilkorven." Is het dan God om de ossen te doen;',
        10: 'of zegt Hij dit eigenlijk om onzentwil? Ja, om ons werd het geschreven; want de ploeger moet ploegen op hoop, en de dorser moet hopen, zijn deel te ontvangen.',
        11: 'Zo we u het geestelijke hebben gezaaid, is het dan zo buitengewoon, als we van u het vleselijke zouden maaien?',
        12: 'Wanneer anderen op u rechten kunnen doen gelden, wij niet veel meer? Toch hebben we van dat recht geen gebruik gemaakt, maar van alles afstand gedaan, om het Evangelie van Christus niets in de weg te leggen.',
        13: 'Weet gij niet, dat zij die dienst doen in het heiligdom, ook van het heiligdom eten; en dat zij die het altaar bedienen, ook met het altaar opdelen?',
        14: 'Zo heeft eveneens de Heer verordend, dat zij, die het Evangelie verkondigen, ook van het Evangelie zouden leven.',
        15: 'Welnu, ik voor mij heb van dit alles geen gebruik gemaakt. Ook schrijf ik het niet, om het op mij toe te passen; want liever wil ik sterven, dan me mijn roem laten ontnemen.',
        16: 'Immers niet het verkondigen zelf van het Evangelie strekt me tot roem. Want dit is mijn plicht. Ja, wee mij, zo ik het Evangelie niet zou verkondigen.',
        17: 'Welnu, wanneer ik iets doe uit vrije beweging, dan heb ik verdienste; maar doe ik het op bevel, dan vervul ik slechts de taak van beheerder.',
        18: 'Waarin ligt dus mijn verdienste? Hierin, dat ik bij mijn prediking het Evangelie om niet verkondig, zonder gebruik te maken van mijn recht, dat aan het preken verbonden is.',
        19: 'Ja, ofschoon ik vrij sta tegenover allen, heb ik me toch tot slaaf van allen gemaakt, om er zoveel mogelijk te winnen.',
        20: 'Voor de Joden ben ik als een jood geworden, om Joden te winnen; voor hen, die onder de Wet zijn, als een, die onder de Wet staat, —ook al sta ik niet onder de Wet, —om hen te winnen, die onder de Wet staan.',
        21: 'Voor hen, die zonder Wet zijn, als een zonder Wet, —hoewel niet zonder wet van God, maar onder Christus’ wet, om hen te winnen, die zonder Wet zijn.',
        22: 'Voor de zwakken ben ik zwak geworden, om de zwakken te winnen. Voor allen ben ik van alles geworden, om met alle middelen enigen te redden.',
        23: 'Welnu, dit alles doe ik om het Evangelie, om daaraan deel te mogen hebben.',
        24: 'Weet gij niet, dat de wedlopers in het renperk wèl allen lopen, maar dat slechts één de prijs behaalt. Loopt dan zó, dat ook gij hem moogt winnen.',
        25: 'En hij, die in het worstelperk optreedt, legt zich een volkomen onthouding op. Zij doen het, om een vergankelijke kroon te ontvangen, wij om een onvergankelijke.',
        26: 'En daarom loop ik niet als een, die in den blinde voortholt, en worstel ik niet als een, die in de lucht slaat.',
        27: 'Maar het is mijn eigen lichaam, dat ik beuk en dat ik er onder houd, om na heraut geweest te zijn voor anderen, zelf niet afgewezen te worden.',
    },
    10: {
        1: 'Ik wil niet, broeders, dat gij er geen acht op zoudt slaan, hoe onze vaders allen onder de wolk waren, allen door de zee heentrokken,',
        2: 'en allen door wolk en zee in Moses werden gedoopt;',
        3: 'hoe ze allen dezelfde geestelijke spijs hebben gegeten;',
        4: 'hoe ze allen dezelfde geestelijke drank hebben gedronken; want ze dronken uit een geestelijke rots, die hen vergezelde, en die rots was Christus.',
        5: 'Toch heeft God in de meesten van hen geen welbehagen gehad, want ze werden neergeveld in de woestijn;',
        6: 'en dit is geschied als voorafbeelding voor ons, opdat wij geen begeerte naar het kwade zouden hebben, zoals zij dat hebben gehad.',
        7: 'Weest ook geen afgodendienaars, zoals sommigen van hen; gelijk geschreven staat: "Het volk zat neer, om te eten en te drinken, en men ging zich vermaken."',
        8: 'Laten we ook geen ontucht bedrijven, zoals sommigen van hen ontucht bedreven; en op één dag vielen er drie en twintig duizend.',
        9: 'Tarten we ook den Heer niet, zoals sommigen van hen hebben gedaan; en ze kwamen om door de slangen.',
        10: 'Mort ook niet, zoals sommigen van hen hebben gemord; en ze werden uitgeroeid door den verderfengel.',
        11: 'Dit alles nu overkwam hun als een voorafbeelding voor ons, en het werd opgeschreven tot waarschuwing voor ons, die het einde der tijden beleven.',
        12: 'Dus, wie meent te staan, zie toe, dat hij niet valt!',
        13: 'Gij hebt geen bovenmenselijke bekoring te doorstaan gehad. God is getrouw; Hij zal niet toelaten, dat gij boven uw krachten bekoord wordt, maar met de bekoring zal Hij ook het middel geven, om ze te kunnen doorstaan.',
        14: 'En daarom, mijn geliefden, vlucht de afgoderij!',
        15: 'Ik spreek tot verstandigen; beoordeelt dus zelf, wat ik zeggen ga.',
        16: 'Is de kelk der zegening, die wij zegenen, geen deelgenootschap aan het Bloed van Christus; is het brood, dat wij breken, geen deelgenootschap aan het Lichaam van Christus?',
        17: 'Omdat het één Brood is, daarom zijn wij, hoe talrijk ook, één lichaam; want allen hebben wij deel aan het éne Brood.',
        18: 'Beschouwt het Israël naar het vlees; zijn zij, die de offerspijzen eten, niet in gemeenschap met het altaar?',
        19: 'Wat wil ik hiermee zeggen? Dat het offervlees iets is, of dat een afgod iets is?',
        20: 'Neen, maar wat ze offeren, offeren ze aan duivels en niet aan God. En ik wil niet, dat gij in gemeenschap staat met de duivels.',
        21: 'Gij kunt de kelk des Heren niet drinken en de kelk der duivels. Gij kunt geen deel hebben aan de Tafel des Heren en aan de tafel der duivels.',
        22: 'Of zouden we den Heer soms willen uitdagen? Zijn wij soms sterker dan Hij?',
        23: 'Alles is geoorloofd! Maar niet alles is heilzaam! Alles is geoorloofd! Maar niet alles is stichtend.',
        24: 'Niemand zoeke zijn eigen belang, maar dat van den naaste.',
        25: 'Al wat in de vleeshal verkocht wordt, moogt gij eten, zonder verder onderzoek te doen tot geruststelling van uw geweten.',
        26: 'Want: "Aan den Heer behoort de aarde met wat ze bevat."',
        27: 'Zo een ongelovige u uitnodigt, en gij wilt er heen gaan, eet dan gerust al wat u wordt voorgezet, zonder verder onderzoek te doen tot geruststelling van het geweten.',
        28: 'Maar zo iemand u zegt: "dit is offervlees," eet er dan niet van, zowel om hem, die er u opmerkzaam op maakte, als om gewetenswil.',
        29: 'Ik bedoel niet uw eigen geweten, maar dat van den ander. Waarom toch zou mijn vrijheid op zich zelf genomen afgemeten worden naar het geweten van een ander?',
        30: 'Wanneer ik na dankzegging van iets geniet, waarom zou ik gesmaald worden om iets, waarvoor ik dankzegging uitspreek?',
        31: 'Derhalve, of gij eet, of drinkt, of wat gij ook doet, doet alles ter ere Gods!',
        32: 'Geeft geen aanstoot aan Joden of heidenen, noch aan de Kerk van God;',
        33: 'zoals ook ikzelf allen in ieder opzicht terwille ben, en niet mijn eigen belang zoek, maar dat van de grote menigte, opdat ze behouden wordt.',
    },
    11: {
        1: 'Weest mijn navolgers, zoals ik het ben van Christus!',
        2: 'Ik prijs u, omdat gij bij allerlei zaken aan mij denkt, en vasthoudt aan de voorschriften, die ik u gegeven heb.',
        3: 'Welnu, ik wil, dat gij wèl bedenkt: het hoofd van iederen man is Christus; het hoofd van de vrouw is de man; het hoofd van Christus is God.',
        4: 'Iedere man, die bidt of profeteert met bedekt hoofd, doet zijn hoofd schande aan.',
        5: 'Iedere vrouw daarentegen, die blootshoofds bidt of profeteert, doet haar hoofd schande aan; want dat is juist hetzelfde, als deed ze het met geschoren hoofd.',
        6: 'Ja, zo een vrouw zich niet bedekken wil, dan moet ze zich ook maar de haren doen knippen; en zo het voor een vrouw een schande is, zich kaal te laten knippen of scheren, dan moet ze zich ook maar bedekken.',
        7: 'De man moet zijn hoofd niet bedekken, daar hij het evenbeeld is en de glorie van God; maar de vrouw is de glorie van den man.',
        8: 'Want de man is niet uit de vrouw, maar de vrouw is uit den man;',
        9: 'en de man is niet geschapen om de vrouw, maar de vrouw om den man.',
        10: 'En daarom moet de vrouw een macht over haar hoofd behouden ter wille der engelen.',
        11: 'Toch blijft het waar: naar ‘s Heren plan is een vrouw er niet zonder man, maar ook is een man er niet zonder vrouw.',
        12: 'Want zoals de vrouw uit den man is ontstaan, zo ontstaat ook weer de man door de vrouw; en dit alles naar Gods beschikking.',
        13: 'Oordeelt nu zelf: Is het betamelijk, dat een vrouw bidt met onbedekt hoofd?',
        14: 'Leert toch de natuur zelf u niet, dat het voor den man een schande is, lang haar te dragen;',
        15: 'terwijl het voor de vrouw een eer is, wanneer ze lang haar draagt; want de haardos is haar gegeven bij wijze van sluier.',
        16: 'En zo iemand nog andere bewijzen verlangt: wij hebben zulke gebruiken niet, en de gemeenten Gods evenmin.',
        17: 'Bij de nu volgende vermaning kan ik u niet prijzen. Want gij komt niet samen tot uw heil, maar tot uw onheil.',
        18: 'Vooreerst toch hoor ik, dat er bij uw bijeenkomsten in de kerk verdeeldheid onder u heerst; en gedeeltelijk geloof ik dit ook.',
        19: 'Want het is nodig, dat er scheuringen onder u zijn, wil het blijken, wie onder u standvastig is.',
        20: 'Wanneer gij bijeen komt, dan is dat geen nuttigen van de Maaltijd des Heren.',
        21: 'Want iedereen begint zijn eigen maal vooruit te eten; en zó is de een hongerig, de ander over-verzadigd.',
        22: 'Hebt gij dan geen huizen, om te eten en te drinken? Of durft gij de kerk van God verachten, en hen die niets bezitten, vernederen? Wat zal ik u zeggen? Zal ik u prijzen? Op dit punt prijs ik u zeker niet.',
        23: 'Want ik zelf heb van den Heer ontvangen, wat ik u ook heb overgeleverd; dat de Heer Jesus in de nacht, dat Hij verraden werd, brood nam,',
        24: 'een dankzegging sprak, het brak en zeide: "Dit is mijn Lichaam, dat voor u wordt overgeleverd. Doet dit tot mijn gedachtenis."',
        25: 'Zo ook na de maaltijd de kelk, zeggende: "Deze kelk is het nieuwe Verbond in mijn Bloed. Doet dit, zo dikwijls gij drinkt, tot mijn gedachtenis."',
        26: 'Welnu, zo dikwijls gij dit brood eet en de kelk drinkt, verkondigt gij de dood des Heren, totdat Hij komt.',
        27: 'Wie dus op onwaardige wijze het brood eet of de kelk des Heren drinkt, bezondigt zich aan het Lichaam en Bloed des Heren.',
        28: 'Laat dus een ieder zichzelf onderzoeken, en dan eerst eten van het brood en drinken van de kelk.',
        29: 'Want wie eet en drinkt, eet en drinkt zich een oordeel, zo hij het Lichaam niet naar waarde beoordeelt.',
        30: 'Daarom zijn er onder u zoveel zwakken en zieken, en zijn er zovelen ontslapen.',
        31: 'Zo we onszelf naar waarheid hadden beoordeeld, zouden we niet geoordeeld worden.',
        32: 'Welnu, als we door den Heer worden gèoordeeld, dan is dat voor ons een les, om niet met de wereld vèroordeeld te worden.',
        33: 'En daarom, mijn broeders, wanneer gij bijeenkomt om te eten, blijft dan op elkander wachten.',
        34: 'Zo iemand honger heeft, dan moet hij thuis maar eten. Anders komt gij tot uw oordeel bijeen. De andere zaken zal ik wel regelen, wanneer ik kom.',
    },
    12: {
        1: 'Wat de Geestesgaven betreft, broeders, wil ik u niet in het onzekere laten;',
        2: 'gij weet het, toen gij heidenen waart, was het blindelings, dat gij naar de stomme afgoden werdt heengedreven.',
        3: 'Daarom maak ik u bekend, dat niemand, die spreekt door Gods Geest, zegt: "Vervloekt zij Jesus;" en dat niemand zeggen kan: "Heer Jesus," dan door den heiligen Geest.',
        4: 'Welnu, er is verscheidenheid van genadegaven, maar er is slechts één Geest;',
        5: 'en verscheidenheid van bedieningen, maar slechts één Heer;',
        6: 'en verscheidenheid van werkingen, maar slechts één God, die alles in allen werkt.',
        7: 'En aan een ieder wordt de Geestesuiting geschonken, om er nut mee te stichten.',
        8: 'Den één wordt het woord der wijsheid gegeven door den Geest, den ander het woord der kennis door denzelfden Geest,',
        9: 'een ander het geloof door denzelfden Geest, een ander de gaven der genezing door den énen Geest.',
        10: 'Aan anderen weer het werken van wonderen, of de profetie, of de onderscheiding der geesten, of de veelheid van talen, of de vertolking der talen;',
        11: 'maar dit alles werkt één en dezelfde Geest, die ieder toedeelt, zoals het Hem goeddunkt.',
        12: 'Want zoals het lichaam één is, ofschoon het veel leden heeft, en van de andere kant al de leden van het lichaam, hoe talrijk ook, één lichaam vormen, zo ook Christus.',
        13: 'Allen toch, Joden of heidenen, slaven of vrijen, allen zijn we in één Geest tot één lichaam gedoopt, en allen zijn we met één Geest gedrenkt.',
        14: 'Want ook het lichaam bestaat niet uit één lid, maar uit meerdere leden.',
        15: 'Al zei de voet: omdat ik geen hand ben, behoor ik niet tot het lichaam; toch behoort hij tot het lichaam.',
        16: 'En al zei het oor: omdat ik geen oog ben, behoor ik niet tot het lichaam; toch behoort het tot het lichaam.',
        17: 'Zo het lichaam één en al oog was, waar bleef het gehoor; was het één en al gehoor, waar bleef dan de reuk?',
        18: 'Maar in werkelijkheid heeft God de leden, elk in het bijzonder, een plaats in het lichaam gegeven, zoals het Hem heeft behaagd.',
        19: 'En van de andere kant, zo alle nu eens één lid vormden, waar bleef dan het lichaam?',
        20: 'Maar in werkelijkheid zijn er veel leden, doch slechts één lichaam.',
        21: 'Het oog kan niet tot de hand zeggen: Ik heb u niet nodig; het hoofd niet tot de voeten: Ik heb u niet nodig.',
        22: 'Integendeel, juist de schijnbaar zwakkere leden van het lichaam zijn het meest noodzakelijk;',
        23: 'wat ons in het lichaam minder edel toeschijnt, bekleden we met meer luister; en juist onze oneerbare ledematen ontvangen groter kiesheid;',
        24: 'onze eerbare leden hebben dat niet nodig. Ja, God heeft het lichaam zó samengesteld, dat Hij groter eer gaf aan wat misdeeld is,',
        25: 'opdat er in het lichaam geen tweedracht zou heersen, maar de leden gelijke zorg voor elkaar zouden dragen.',
        26: 'En wanneer één lid lijdt, lijden alle leden mee; komt één lid in aanzien, alle leden delen in zijn vreugde.',
        27: 'Welnu, gij zijt het lichaam van Christus, en ieder in het bijzonder zijn leden.',
        28: 'En in de Kerk heeft God den één aangesteld tot apostel, een ander tot profeet, een derde tot leraar; dan komen de wonderen, dan de gaven der genezing, hulpbetoon, bestuur, de veelheid van talen.',
        29: 'Zijn allen soms apostelen? Allen profeten? Allen leraars?',
        30: 'Hebben allen de wondermacht, allen de gaven der genezing? Spreken allen in talen, vertolken allen?',
        31: 'Gij hunkert naar de hoogste gaven? Ik wijs u een weg, die nog veel hoger ligt.',
    },
    13: {
        1: 'Al spreek ik de talen van mensen en engelen, Maar ik heb de liefde niet: Ik ben een rinkelend bekken, Of een rammelend cymbaal.',
        2: 'Al heb ik de gave der profetie, Al bezit ik alle geheimen en kennis, Al heb ik het volle geloof, dat bergen verzet: Zonder liefde ben ik niets.',
        3: 'Al schenk ik weg al wat ik heb, Al geef ik mijn lichaam, om mij te laten verbranden: Zo ik de liefde niet heb, Het dient mij tot niets.',
        4: 'De liefde is geduldig, De liefde is goedertieren, De liefde is niet afgunstig, Niet pronkzuchtig, niet verwaand.',
        5: 'Zij handelt niet onedel, En zoekt zichzelve niet, Zij laat zich niet verbitteren, En rekent het kwade niet aan.',
        6: 'Over onrecht is zij niet blijde, Maar over de waarheid verheugd.',
        7: 'Alles bedekt zij, alles gelooft zij, Alles hoopt zij, alles duldt zij.',
        8: 'De liefde: zij vergaat nimmer! Maar profetieën: zij houden op, En talen: zij zullen verstommen, En kennis: zij zal vergaan.',
        9: 'Want ons kennen is ten halve, Ons profeteren slechts ten dele;',
        10: 'Maar komt eens het volmaakte, Het onvolmaakte verdwijnt.',
        11: 'Toen ik een kind was, sprak ik als kind, Voelde ik als kind, dacht ik als kind;',
        12: 'Nu ik een man ben, Leg ik het kinderlijke af. Thans zien wij in een wazige spiegel; Straks aangezicht tot aangezicht. Thans ken ik slechts ten halve; Straks ten volle, zoals ik zelf ben gekend.',
        13: 'Zo blijven bestaan Geloof, hoop en liefde, Drie in getal; Maar de grootste daarvan is de liefde.',
    },
    14: {
        1: 'Jaagt de liefde na, en streeft dan naar de Geestesgaven, doch naar het profeteren het meest.',
        2: 'Wie talen spreekt, spreekt niet voor mensen, maar voor God; want niemand verstaat hem, maar in geestverrukking spreekt hij geheimzinnige woorden uit.',
        3: 'Maar wie profeteert, spreekt voor mensen tot stichting, vermaning en troost.',
        4: 'Wie talen spreekt, sticht zichzelf; maar wie profeteert, sticht de gemeente.',
        5: 'Ik wens u allen toe, dat gij in talen moogt spreken, maar meer nog, dat gij moogt profeteren; want hij die profeteert, overtreft hem die in talen spreekt, behalve als hij het ook vertolkt, zodat de gemeente er stichting uit trekt.',
        6: 'Welnu broeders, als ik tot u kwam en in talen sprak, wat nut zou ik u stichten, zo ik niet tevens u toesprak met openbaring of kennis, met profetie of met lering?',
        7: 'Het gaat er mee als met de levenloze muziekinstrumenten, fluit of citer; zo ze verwarde geluiden voortbrengen, hoe komt men dan te weten, wat er gefloten of getokkeld wordt?',
        8: 'En zo een bazuin een bazuin onzekere klank uitstoot, wie maakt zich dan ten strijde gereed?',
        9: 'Zo gaat het ook u met uw taal; zo gij geen verstaanbare woorden doet horen, hoe zal men dan begrijpen wat er gesproken wordt? Gij spreekt dan tegen de wind!',
        10: 'Er zijn in de wereld wie weet hoeveel talen, en geen enkele is er onverstaanbaar.',
        11: 'Maar wanneer ik de zin der taal niet versta, dan ben ik een barbaar voor iemand, die met me spreekt, en hij voor mij.',
        12: 'Zo moet ook gij, nu gij toch zo naar geestverrukking hunkert, er ijverig naar streven, om daarmee de stichting der gemeente zoveel mogelijk te bevorderen.',
        13: 'Dus, hij die in talen spreekt, moet bidden, dat hij ook vertolken kan.',
        14: 'Want wanneer ik in talen bid, dan bidt wel mijn geest, maar mijn verstand dient voor niets.',
        15: 'Hoe moet het dan? Ik wil bidden met mijn geest, maar ook bidden met mijn verstand; ik wil lofzingen met mijn geest, maar ook lofzingen met mijn verstand.',
        16: 'Want wanneer ge een dankzegging uitspreekt in geestverrukking, hoe zal dan iemand, die tot de oningewijden behoort, het "Amen" kunnen zeggen op uw dankzegging, daar hij niet weet, wat ge zegt.',
        17: 'Zeker, gij van uw kant spreekt een schoon dankgebed uit, maar de ander wordt er niet door gesticht.',
        18: 'Ik dank God, dat ik meer dan gij allen in talen spreek;',
        19: 'maar toch wil ik in de gemeente liever vijf woorden spreken met mijn verstand, om ook anderen te onderrichten, dan tienduizend in een taal.',
        20: 'Broeders, weest geen kinderen in uw oordeel, maar weest onmondig in het kwaad en rijp in uw oordeel.',
        21: 'In de Wet staat geschreven:"Door mensen met vreemde taal, En door lippen van vreemden Zal Ik spreken tot dit volk; Ook dan zullen ze niet naar Mij horen. Spreekt de Heer."',
        22: 'De talen zijn dus een teken niet voor de gelovigen, maar voor de ongelovigen; de profetie daarentegen is niet voor de ongelovigen, maar voor hen, die geloven.',
        23: 'Veronderstelt nu eens, dat heel de gemeente op één plaats bijeen is en allen in talen spreken, en dat er een oningewijde of een ongelovige binnenkomt; zullen ze dan niet zeggen, dat gij waanzinnig zijt?',
        24: 'Maar zo allen profeteren, en er komt een ongelovige of oningewijde binnen, dan wordt hij door allen overtuigd, door allen geoordeeld,',
        25: 'en zijn hartsgeheimen worden blootgelegd; dan zal hij neervallen op zijn aangezicht, God aanbidden, en het openlijk verkondigen, dat waarlijk God in uw midden is.',
        26: 'Hoe moet het dan, broeders? Bij uw samenkomsten mag elk iets hebben; de één een psalm, de ander een onderrichting, openbaring, taal of vertolking. Maar alles moet tot stichting geschieden.',
        27: 'Wanneer men in talen spreekt, dan geschiede het door twee, hoogstens drie, en op de beurt; en één moet het vertolken.',
        28: 'Zo er geen tolk aanwezig is, dan moet men zwijgen in de gemeente, en slechts spreken voor zichzelf en voor God.',
        29: 'Van de profeten mogen er twee of drie het woord voeren, en de anderen moeten het beoordelen.',
        30: 'En wanneer een ander, die er bij zit, een openbaring ontvangt, dan moet de eerste zwijgen.',
        31: 'Zeker, als het úw beurt is, moogt gij allen profeteren, opdat allen er uit leren, en allen worden vertroost.',
        32: 'Profeten-geesten toch zijn aan de profeten zelf onderworpen;',
        33: 'want God is geen God van wanorde, maar van vrede. Zoals het in alle gemeenten der heiligen gebeurt,',
        34: 'moeten de vrouwen in de bijeenkomsten zwijgen. Want het is haar taak niet, te spreken; maar ze moeten onderdanig zijn, zoals de Wet het ook zegt.',
        35: 'En wanneer ze inlichtingen verlangen, dan moeten ze thuis haar eigen man er naar vragen. Want het is voor een vrouw onbetamelijk, in de kerk het woord te voeren.',
        36: 'Is het woord Gods soms van u uitgegaan, of is het alleen tot u doorgedrongen?',
        37: 'Zo iemand zich voor een profeet of begenadigde houdt, hij erkenne, dat het een gebod des Heren is, wat ik u schrijf.',
        38: 'En zo hij het miskent, dan worde hij zelf miskend.',
        39: 'Zo dan, mijn broeders, beijvert u om te profeteren, en belemmert het spreken in talen niet.',
        40: 'Maar laat alles betamelijk en ordelijk gebeuren.',
    },
    15: {
        1: 'Broeders, ik herinner u aan het Evangelie, dat ik u heb gepreekt, dat gij ook hebt aangenomen, waarop gij gegrondvest zijt,',
        2: 'en waardoor gij zult worden gered, zo gij vasthoudt aan de zin, waarin ik het u heb verkondigd; in de veronderstelling althans, dat gij niet helemaal onnadenkend zijt gaan geloven.',
        3: 'Want vóór alles heb ik u overgeleverd, wat ik zelf had ontvangen: Christus is voor onze zonden gestorven volgens de Schriften;',
        4: 'Hij is begraven, de derde dag is Hij verrezen volgens de Schriften;',
        5: 'en Hij is verschenen aan Kefas, daarna aan de twaalf.',
        6: 'Vervolgens is Hij verschenen aan meer dan vijfhonderd broeders tegelijk, waarvan de meesten thans nog leven, en slechts enkelen zijn ontslapen.',
        7: 'Daarna is Hij verschenen aan Jakobus, toen aan alle Apostelen.',
        8: 'Het laatst van allen verscheen Hij aan mij als aan de misdracht.',
        9: 'Ja waarlijk, ik ben de allerminste der Apostelen, niet waardig Apostel genoemd te worden, daar ik Gods Kerk heb vervolgd;',
        10: 'maar door Gods genade ben ik, wat ik ben, en de genade, die Hij me schonk, is niet ijdel geweest, maar meer dan alle anderen heb ik gezwoegd; niet ik, maar Gods genade met mij.',
        11: 'Of ik het nu ben, of de anderen: zó preken wij, en zó hebt gij het geloofd!',
        12: 'Welnu, indien van Christus gepreekt wordt, dat Hij van de doden is verrezen, hoe kunnen dan sommigen onder u zeggen: De opstanding der doden is onmogelijk?',
        13: 'Indien de opstanding der doden onmogelijk is, dan is ook Christus niet verrezen.',
        14: 'Maar zo Christus niet is verrezen, dan is onze prediking ijdel, ijdel ook uw geloof.',
        15: 'Dan blijken we bovendien valse getuigen van God te zijn; want we hebben van God getuigd, dat Hij Christus heeft opgewekt; terwijl Hij Hem niet opgewekt heeft, zo er inderdaad geen doden verrijzen.',
        16: 'Want zo er geen doden verrijzen, dan is ook Christus niet verrezen.',
        17: 'Maar zo Christus niet is verrezen, dan is uw geloof zonder nut, en zijt gij nog in uw zonden;',
        18: 'dan zijn ook zij verloren, die in Christus ontsliepen.',
        19: 'Zo we alleen voor dit leven onze hoop stellen op Christus, dan zijn we de meest beklagenswaardige van alle mensen.',
        20: 'Maar neen, Christus is van de doden verrezen, als Eersteling onder hen, die ontslapen zijn.',
        21: 'Want omdat door een mens de dood is gekomen, daarom ook is door een Mens de opstanding der doden.',
        22: 'Zoals allen immers sterven door hun gemeenschap met Adam, zo zullen ook allen door hun gemeenschap met Christus herleven.',
        23: 'Maar iedereen naar eigen rang. Christus als Eersteling; dan zij, die Christus toebehoren bij zijn komst.',
        24: 'Daarna komt het einde, als Hij het koningschap aan God en den Vader overdraagt, na alle heerschappij en alle macht en kracht te hebben vernietigd.',
        25: 'Want Hij moet Koning zijn, totdat "Hij alle vijanden onder zijn voeten heeft gelegd".',
        26: 'En de dood is de laatste vijand, die vernietigd wordt;',
        27: 'want àlles heeft Hij onder zijn voeten gelegd. Wanneer Hij nu zegt, dat àlles onderworpen is, dan is heel duidelijk Hijzelf uitgezonderd, die alles aan Hem onderwierp.',
        28: 'Zodra dus alles aan Hem onderworpen is, zal ook de Zoon Zichzelf onderwerpen aan Dengene, die alles aan Hem onderwierp, opdat God zij: Alles in allen.',
        29: 'Wat toch zullen zij aanvangen, die zich voor de doden laten dopen, zo er helemaal geen doden verrijzen? Waarom dan laten ze zich voor hen dopen?',
        30: 'En waartoe dient het dan, dat wijzelf ieder uur in gevaar verkeren?',
        31: 'Elke dag zie ik de dood van nabij; broeders, zowaar ik op u roem, in Christus Jesus onzen Heer.',
        32: 'Als ik te Éfese met wilde dieren had gevochten, zoals de mensen het wilden, wat zou het me hebben gebaat? Wanneer de doden niet verrijzen, laat ons dan maar eten en drinken, want morgen gaan we dood.',
        33: 'Laat u niet verleiden: Slechte omgang bederft goede zeden.',
        34: 'Gebruikt uw nuchter verstand, zoals het behoort, en zondigt niet. Want er zijn er, die van God geen begrip hebben. Ik zeg het tot uw beschaming.',
        35: 'Maar, zal iemand zeggen: Op welke wijze verrijzen de doden; met wat voor lichaam komen ze terug?',
        36: 'Gij dwaas! Wat ge zelf zaait, wordt niet levend, zo het niet gestorven is;',
        37: 'bovendien wat ge zaait, is niet de uitwendige gestalte, die te voorschijn treedt, doch een naakte korrel, bijvoorbeeld van graan of iets anders;',
        38: 'maar God geeft er een gestalte aan, zoals het Hem behaagt, en wel aan ieder zaad zijn eigen gestalte.',
        39: 'Alle vlees is niet hetzelfde; maar anders is dat van mensen, anders dat van het vee, van vogels en vissen.',
        40: 'Er zijn hemellichamen en aardse lichamen, maar de glans der hemelse is anders dan die der aardse.',
        41: 'Anders is de glans van de zon, anders de glans van de maan, anders de glans van de sterren; zelfs de ene ster verschilt van de andere in glans.',
        42: 'Zo is het ook met de opstanding der doden: Het wordt gezaaid in bederf, Het verrijst onbederflijk.',
        43: 'Het wordt gezaaid in oneer, Het verrijst in heerlijkheid. Het wordt gezaaid in zwakheid, Het verrijst in kracht.',
        44: 'Een ziele-lichaam wordt gezaaid, Een geestelijk lichaam verrijst! Bestaat er een ziele-lichaam, er bestaat ook een geestelijk lichaam.',
        45: 'Aldus staat er ook geschreven: "De eerste mens Adam werd een levende ziel;" de laatste Adam een levendmakende Geest.',
        46: 'Niet het geestelijke gaat vooraf, maar wel het bezielde; daarna komt het geestelijke.',
        47: 'De eerste mens was uit de aarde, aards; de tweede Mens is uit de hemel.',
        48: 'Welnu, zoals de aardse was, zo zijn ook de aardse; zoals de Hemelse was, zo zullen ook de hemelse zijn;',
        49: 'en zoals we de gestalte van den aardsen hebben gedragen, zo moeten we ook de gestalte van den Hemelsen dragen.',
        50: 'Ik bedoel dit, broeders: vlees en bloed kunnen geen deel hebben aan het koninkrijk Gods, en het bederf heeft geen deel aan het onbederflijke.',
        51: 'Zie ik deel u een geheimenis mee: Niet allen zullen wij ontslapen, maar wel allen van gedaante veranderen;',
        52: 'plotseling, in een oogwenk, bij de laatste stoot der bazuin. Want zodra de bazuin zal schallen, zullen de doden verrijzen, onbederflijk, maar wij van gedaante veranderen.',
        53: 'Want dit bederflijke moet met het onbederflijke worden bekleed; dit sterflijke met onsterflijkheid.',
        54: 'En zodra dit bederflijke met het onbederflijke is bekleed, en dit sterflijke met onsterflijkheid, wordt het woord vervuld, dat geschreven staat: De dood is verzwolgen in overwinning.',
        55: 'Dood, waar is uw overwinning? Dood, waar is uw prikkel?',
        56: 'De prikkel des doods is de zonde; de kracht der zonde de Wet.',
        57: 'Maar God zij dank, die ons de overwinning geeft door Jesus Christus onzen Heer.',
        58: 'En daarom, mijn geliefde broeders, staat onbewegelijk vast, weest ten allen tijde rijk in ‘s Heren werk; gij weet, dat uw arbeid niet vergeefs is in den Heer.',
    },
    16: {
        1: 'Wat de collecte betreft ten bate der heiligen, zo moet ook gij doen, zoals ik het in de kerken van Galátië geregeld heb.',
        2: 'Op de eerste dag van iedere week moet ieder van u naar vermogen iets terzijde leggen en opsparen, opdat de collecten niet eerst beginnen, als ik kom.',
        3: 'Bij mijn komst zal ik dan hen, die gij daarvoor geschikt acht, met brieven naar Jerusalem zenden, om uw liefdegave over te brengen.',
        4: 'Is het de moeite waard, dat ik zelf ga, dan kunnen ze met me mee gaan.',
        5: 'Ik zal naar u toe komen, wanneer ik Macedónië door ben. Want Macedónië trek ik slechts door;',
        6: 'maar bij u zal ik, zo mogelijk, langer vertoeven, misschien wel de winter doorbrengen, zodat gij me kunt uitrusten, wanneer ik verder reis.',
        7: 'Want ik wil u ditmaal niet in het voorbijgaan bezoeken, maar ik hoop enige tijd bij u te blijven, zo de Heer het toelaat.',
        8: 'Tot Pinksteren zal ik te Éfese blijven;',
        9: 'want een grote en zware deur staat voor me open, en de tegenstanders zijn velen.',
        10: 'Wanneer Timóteus komt, zorgt dan, dat hij zonder vrees bij u kan zijn, want hij verricht ‘s Heren werk, evenals ikzelf.',
        11: 'Niemand schiete dus te kort in eerbied voor hem. Doet hem in vrede uitgeleide, opdat hij naar mij heen komt; want ik en de broeders wachten op hem.',
        12: 'Wat broeder Apollo betreft, ik heb hem dringend verzocht, naar u heen te gaan tezamen met de broeders; maar hij heeft volstrekt geweigerd, om thans te vertrekken. Hij zal gaan, wanneer het hem gelegen komt.',
        13: 'Weest waakzaam, staat vast in het geloof; blijft mannen, weest kloek.',
        14: 'Alles geschiede bij u in liefde.',
        15: 'Broeders, ik heb u nog iets te verzoeken. Gij weet, dat de familie van Stéfanas de eersteling van Achaja is, en dat ze zich ten dienste der heiligen hebben gesteld.',
        16: 'Toont ook gij ontzag voor zulke personen, als aan allen, die met hen meewerken en zwoegen,',
        17: 'Ik verheug me over de aanwezigheid van Stéfanas, Fortunatus en Acháicus; want ze hebben me het gemis van u vergoed,',
        18: 'en mijn geest verkwikt evenals die van u. Waardeert dus zulke mensen.',
        19: 'De gemeenten van Azië groeten u. Aquila en Priska met heel de gemeente, die in hun huis vergadert, laten u bijzonder groeten in den Heer.',
        20: 'Alle broeders groeten u. Groet elkander met een heilige kus.',
        21: 'De groet is van mijn eigen hand: Paulus.',
        22: 'Zo iemand den Heer niet liefheeft, hij zij vervloekt. "Marán-Atá".',
        23: 'De genade van onzen Heer Jesus zij met u!',
        24: 'Mijn liefde is met u allen in Christus Jesus.',
    },
}
